def oracle_factor(n, oracle=None):
    for a in range(2, n):
        from math import gcd
        g = gcd(a, n)
        if 1 < g < n:
            return (g, n // g)
    raise ValueError(f'Cannot factor {n}')

def detect_vanishing_order(oracle, max_depth=100, tol=1e-12):
    for n in range(max_depth):
        if abs(oracle(n)) > tol:
            return n
    return max_depth
